function neighbourFace(shape,happy){return `<svg class="neighbourface" viewBox="0 0 64 64" aria-hidden="true">${shape===1?'<path class="facebody" d="M32 4 61 57H3Z"/>':'<rect class="facebody" x="7" y="7" width="50" height="50" rx="10"/>'}<circle cx="24" cy="33" r="2.8"/><circle cx="40" cy="33" r="2.8"/><path class="facemouth" d="${happy?'M23 41Q32 52 41 41':'M24 47Q32 39 40 47'}"/></svg>`}
/* Two optional discoveries; daily-five progress remains independent. */
const extraGames=[['Time Lens','Look closely. What year are you looking at?','Observation','Curious','3 photos','◉'],['Little Neighbours','Small moves. Surprisingly big changes.','Experiment','Play & learn','Puzzle + sandbox','▲ ■ ▲']];
function renderExtras(){ $('#extras').innerHTML=extraGames.map((g,j)=>{let i=j+5;return `<button class="card" data-extra="${i}"><div class="cardtop"><span>${g[2]}</span><span class="level">NEW · ${levelName()}</span></div><div class="art" aria-hidden="true">${g[5]}</div><h3>${g[0]}</h3><p>${g[1]}</p><div class="cardbottom"><span>${state(i).done?'✓ Explored today':g[4]}</span><span>↗</span></div></button>`}).join('');document.querySelectorAll('[data-extra]').forEach(b=>b.onclick=()=>openExtra(+b.dataset.extra))}
function openExtra(i){active=i;state(i).started=true;persist();let g=extraGames[i-5];$('#gtype').textContent='A little extra · '+g[2];$('#gtitle').textContent=g[0];$('#board').innerHTML='';$('#actions').innerHTML='';msg('');if(i===5)timeLens();else neighbours();if(!$('#game').open)$('#game').showModal()}
const baseSetup=setup;setup=function(){baseSetup();renderExtras()};
function photoSet(d){let r=rng(puzzleSeed(d)+'photographs-v2'),indian=shuffle(PHOTO_BANK.filter(p=>p.india),r),others=shuffle(PHOTO_BANK.filter(p=>!p.india),r);return [indian[0],...shuffle([...indian.slice(1),...others],r).slice(0,2)]}
function timeLens(){let s=state(5);if(!s.photoIds){s.photoIds=(s.answers?.length?shuffle(PHOTO_BANK.slice(0,6),rng(day+'photographs')).slice(0,3):photoSet(day)).map(p=>p.image)}let set=s.photoIds.map(id=>PHOTO_BANK.find(p=>p.image===id));persist();s.answers||=[];let index=Math.min(s.answers.length,2);$('#rules').textContent='Three real archive photographs. Slide or type your year, then discover the story. Up to 1,000 points each; every year away costs 20 points. Indian history meets aviation and space. A small archive collection; photographs will repeat. Gentle gives a date window, Medium gives a visual clue, Tricky gives just the photograph.';function draw(){ $('#actions').innerHTML='';if(s.answers.length===3){$('#board').innerHTML=`<div class="photoresult"><span class="eyebrow">A LITTLE JOURNEY THROUGH TIME</span><h2>${s.answers.reduce((n,a)=>n+a.points,0)} <small>/ 3,000</small></h2><p>Every photograph has a story. Here are the moments you discovered.</p></div>`+set.map((p,i)=>`<div class="recap"><img src="${p.image}" alt="${p.alt}"><div><strong>${p.year} · ${p.title}</strong><p>You guessed ${s.answers[i].guess} · ${s.answers[i].points} points</p><a href="${p.source}" target="_blank" rel="noopener">Photo & story ↗</a></div></div>`).join('');msg('Three discoveries, at your own pace.');return}let p=set[index],a=s.answers[index],lo=difficulty===0?Math.max(1850,Math.floor(p.year/25)*25):1850,hi=difficulty===0?Math.min(2025,lo+24):2025,start=s.pendingYear||Math.round((lo+hi)/2);$('#board').innerHTML=`<div class="roundline"><span>Photograph ${index+1} of 3</span><span>${s.answers.reduce((n,a)=>n+a.points,0)} points</span></div><div class="photoframe"><img id="archivephoto" src="${p.image}" alt="${p.alt}"><p id="photoerror" hidden>Photo could not load. Please reopen the puzzle to try again.</p></div><label class="yearlabel" for="year">Your guess <input id="year" type="number" min="${lo}" max="${hi}" value="${start}" ${a?'disabled':''}></label><input id="yearslider" aria-label="Guess the photograph year" type="range" min="${lo}" max="${hi}" value="${start}" ${a?'disabled':''}><div class="rangeends"><span>${lo}</span><span>${hi}</span></div><p class="small">${difficulty===0?"A little help: this photograph falls within the date window above.":difficulty===1?"Look for clues: "+p.alt:"Look closely at clothing, technology and surroundings."}</p><div id="photoreveal"></div><p class="credits">Inspired by <a href="https://www.chronophoto.app/" target="_blank" rel="noopener">Chronophoto</a>. Independent game; archive credits appear after each guess.</p>`;let img=$('#archivephoto');let ready=false;let guessButton;img.onload=()=>{ready=true;if(guessButton)guessButton.disabled=false};img.onerror=()=>{$('#photoerror').hidden=false;if(guessButton)guessButton.disabled=true};const sync=(v)=>{s.pendingYear=+v;$('#year').value=v;$('#yearslider').value=v;persist()};$('#yearslider').oninput=e=>sync(e.target.value);$('#year').oninput=e=>{s.pendingYear=+e.target.value;$('#yearslider').value=e.target.value;persist()};function reveal(){let a=s.answers[index];$('#year').disabled=true;$('#yearslider').disabled=true;$('#photoreveal').innerHTML=`<div class="reveal"><span class="eyebrow">THE YEAR WAS</span><h2>${p.year}</h2><strong>${p.title}</strong><p>${p.story}</p><p>Your guess: ${a.guess} · ${Math.abs(a.guess-p.year)} years away · <strong>${a.points} points</strong></p><a href="${p.source}" target="_blank" rel="noopener">${p.credit} · Source ↗</a></div>`;$('#actions').innerHTML='';action(index===2?'See my discoveries':'Next photograph',()=>{if(index===2){s.done=true;persist();setup();draw()}else{index++;draw()}})}guessButton=action('Reveal the year',()=>{let g=Number($('#year').value);if(!ready&&!(img.complete&&img.naturalWidth))return msg('Let the photograph finish loading first.');if(!Number.isInteger(g)||g<lo||g>hi)return msg(`Choose a whole year between ${lo} and ${hi}.`);s.answers[index]={guess:g,points:Math.max(0,1000-20*Math.abs(g-p.year))};delete s.pendingYear;if(s.answers.length===3)s.done=true;persist();setup();msg('');reveal()});guessButton.disabled=!(img.complete&&img.naturalWidth);if(a)reveal()}draw()}
function adjacent(i,width,size){return [i-width,i+width,i%width?i-1:-1,i%width<width-1?i+1:-1].filter(j=>j>=0&&j<size)}
function neighbourStats(board,width,threshold=0,challenge=false){let statuses=board.map((v,i)=>{if(!v)return null;let ns=adjacent(i,width,board.length).map(j=>board[j]).filter(Boolean),same=ns.filter(n=>n===v).length;return {happy:challenge?same>0&&(difficulty===0||same<ns.length)&&(difficulty!==2||same<=2):ns.length===0||same/ns.length>=threshold/100,same,total:ns.length}});let occupied=statuses.filter(Boolean),edges=occupied.reduce((n,s)=>n+s.total,0),same=occupied.reduce((n,s)=>n+s.same,0);return {statuses,happy:occupied.filter(s=>s.happy).length,total:occupied.length,similarity:edges?Math.round(same/edges*100):0}}
function neighbourModel(d){let solution=Array.from({length:16},(_,i)=>i<12?1+i%2:0),r=rng(puzzleSeed(d)+'neighbours');let board=shuffle(solution,r);return{board,solution}}
function neighbours(){let s=state(6);s.mode||='challenge';s.board||=neighbourModel(day).board;s.history||=[];s.threshold??=35;let selected=null;$('#rules').textContent='A tiny world to think with. Try the daily puzzle, then explore how changing one preference changes a whole neighbourhood.';function draw(){let sandbox=s.mode==='sandbox';if(sandbox&&!s.sandbox){s.sandbox=shuffle([...Array(14).fill(1),...Array(14).fill(2),...Array(8).fill(0)],rng(day+'sandbox'));s.steps=0}let board=sandbox?s.sandbox:s.board,width=sandbox?6:4,st=neighbourStats(board,width,s.threshold,!sandbox);$('#actions').innerHTML='';$('#board').innerHTML=`<div class="modebar"><button class="btn ${sandbox?'secondary':''}" id="challengeMode">Daily puzzle</button><button class="btn ${sandbox?'':'secondary'}" id="sandboxMode">What if…?</button></div><p class="instruction">${sandbox?'Shapes want at least <strong>'+s.threshold+'%</strong> of their occupied neighbours to be the same shape. Only unhappy shapes move. Empty squares and diagonals do not count.':'Help all 12 shapes have <strong>'+(difficulty===0?'at least one same-shape neighbour':difficulty===1?'at least one same-shape and one different-shape neighbour':'one or two same-shape neighbours AND at least one different-shape neighbour')+'</strong>. Only up, down, left and right count. Tap any shape, then an empty space to move it.'}</p>${sandbox?`<label class="sliderlabel" for="preference">Same-shape preference: <strong>${s.threshold}%</strong></label><input id="preference" type="range" min="0" max="100" step="5" value="${s.threshold}">`:''}<div class="neighbourmetrics"><span><strong>${st.happy}/${st.total}</strong> content shapes</span><span><strong>${sandbox?st.similarity+'%':s.history.length}</strong> ${sandbox?'same-shape links':'moves'}</span></div><div class="neighbourgrid" style="grid-template-columns:repeat(${width},1fr)">${board.map((v,i)=>`<button class="neighbour ${v?'shape'+v:'empty'} ${st.statuses[i]?.happy?'content':''} ${selected===i?'selected':''}" data-neighbour="${i}" aria-label="Row ${Math.floor(i/width)+1}, column ${i%width+1}: ${v?(v===1?'triangle':'square')+', '+(st.statuses[i].happy?'content':'unhappy'):'empty space'}">${v?neighbourFace(v,st.statuses[i].happy):'<span aria-hidden="true">+</span>'}</button>`).join('')}</div><p class="small">Smiling = content · worried = needs a neighbour · outlined ring = selected</p>${sandbox?`<p class="experimentnote">${st.happy===st.total?'Everyone is content, so nobody moves. Try a different preference or a fresh arrangement.':'Make a prediction, then advance the world. Does a small preference produce larger clusters?'}<br><br>This is a simplified model, not a prediction about real people. A higher same-shape-link percentage means more clustering.</p>`:''}<p class="credits">Inspired by <a href="https://ncase.me/polygons/" target="_blank" rel="noopener">Parable of the Polygons</a> by Vi Hart & Nicky Case. Original implementation and puzzle rules for Little Sparks.</p>`;
$('#challengeMode').onclick=()=>{s.mode='challenge';selected=null;persist();draw();msg('')};$('#sandboxMode').onclick=()=>{s.mode='sandbox';selected=null;persist();draw();msg('')};if(sandbox)$('#preference').onchange=e=>{s.threshold=+e.target.value;selected=null;persist();draw()};document.querySelectorAll('[data-neighbour]').forEach(b=>b.onclick=()=>{let i=+b.dataset.neighbour;if(!sandbox&&s.done)return msg('You solved today’s neighbourhood! Try the What if…? sandbox.');if(board[i]){if(sandbox&&st.statuses[i].happy)return msg('This shape is content. Only unhappy shapes move in the sandbox.');selected=selected===i?null:i;draw();msg(selected===null?'':'Now choose an empty square.')}else if(selected!==null){if(!sandbox)s.history.push(board.slice());board[i]=board[selected];board[selected]=0;selected=null;persist();draw();check()}else msg('Select a shape first, then an empty square.')});function check(){if(!sandbox&&neighbourStats(s.board,4,0,true).happy===12){s.done=true;persist();setup();msg('A neighbourhood with room for both familiarity and variety. Beautifully done!')}else msg('')}
if(sandbox){action('Advance 10 moves',()=>{let r=rng(day+'step'+(s.steps||0));let moved=0;for(let n=0;n<10;n++){let stats=neighbourStats(s.sandbox,6,s.threshold),unhappy=stats.statuses.map((v,i)=>v&&!v.happy?i:-1).filter(i=>i>=0),empty=s.sandbox.map((v,i)=>v===0?i:-1).filter(i=>i>=0);if(!unhappy.length)break;let from=unhappy[Math.floor(r()*unhappy.length)],to=empty[Math.floor(r()*empty.length)];s.sandbox[to]=s.sandbox[from];s.sandbox[from]=0;moved++;s.steps=(s.steps||0)+1}selected=null;persist();draw();msg(moved?moved+' moves. What changed?':'No unhappy shapes: this world is stable. Change the preference to experiment.')});action('Fresh arrangement',()=>{s.sandbox=null;selected=null;persist();draw();persist();msg('Same starting world, ready for a different experiment.');},true)}else{action('Undo',()=>{if(s.done)return msg('Today’s puzzle is complete. The sandbox is ready to explore.');if(s.history.length)s.board=s.history.pop();selected=null;persist();draw();msg('')},true);action('Start over',()=>{if(s.done)return msg('Today’s puzzle is complete. The sandbox is ready to explore.');s.board=neighbourModel(day).board;s.history=[];selected=null;persist();draw();msg('')},true);action('A gentle hint',()=>msg('Try alternating columns of triangles and squares across three full rows. Vertical neighbours match; horizontal neighbours differ.'),true);if(s.done)msg('✓ You brought the whole neighbourhood together.')}}draw()}
